INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62229753', 62229753, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'RSU PUSAT DR SOERADJI TIRTONEGORO', 'Outsourcing SDM Penunjang dan Administrasi (106 orang)', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Tengah, Klaten (Kab.)', 5354362658, 'December 2025', 'APBN - BADAN LAYANAN UMUM (F)', 1, 1, '1 Paket Pekerjaan', 'Kegiatan pengadaan SDM Penunjang Layanan dan Administrasi pada RSUP Dr. Soeradji Tirtonegoro melalui mekanisme alih daya (outsourcing) dengan penyedia jasa tahun 2026 adalah dalam rangka pemenuhan SDM guna menunjang layanan yang tidak memungkinkan dengan pengadaan melalui formasi ASN (PNS dan PPPK) sebagaimana aturan/ regulasi tentang undang-undang ASN maupun Peraturan Pemerintah tentang Manajemen PNS maupun PPPK. Paket ini kontrak Payung tahun 2025 s.d 2027. Jenis Pekerjaan Kegiatan pengadaan mencakup tenaga kerja non-medis dan pendukung, seperti: 1. Binatu Rumah Sakit 2. Pemulasara jenazah 3. Pengelola Limbah 4. Tenaga administrasi (front office, rekam medis, dll) 5. Pengemudi/driver ambulans 6. Teknisi dan tenaga pemeliharaan fasilitas', 'A. Syarat Umum 1. Warga Negara Indonesia yang bertakwa kepada Tuhan Yang Maha Esa, setia dan taat kepada Pancasila, UUD 1945 dan Negara Kesatuan Republik Indonesia; 2. Berusia paling rendah 18 (delapan belas) tahun dan paling tinggi 35 (tiga puluh lima) tahun yang dibuktikan dengan dokumen kependudukan yang sah bagi tenaga baru, kecuali bagi tenaga outsourcing yang sebelumnya berstatus sebagai pegawai kontrak/harian lepas RSUP Dr. Soeradji Tirtoneoro, usia bisa diatas 35 (tiga puluh lima) tahun dan batas maksimal berusia 58 (lima puluh delapan) Tahun. 3. Memiliki kualifikasi pendidikan yang sesuai dengan persyaratan jabatan yang dibuktikan dengan Ijazah Pendidikan Formal; 4. Sehat jasmani dan rohani yang dibuktikan dengan Surat Keterangan Sehat dari Dokter yang memiliki kewenangan medis; 5. Sebelum atau setelah dinyatakan diterima sebagai Tenaga Outsourcing, wajib mengikuti MCU sesuai aturan yang berlaku. B. Syarat Khusus 1. Untuk semua formasi diutamakan memiliki kemampuan dalam mengoperasikan perangkat komputer dasar (Ms. Office) 2. Untuk formasi pengemudi pimpinan/pengemudi ambulan wajib memiliki SIM A dan diutamakan SIM B [10.45, 11/12/2025] Cahyo Pendukung: Untuk formasi binatu rumah sakit diutamakan berpendidikan SMK tata busana/ punya sertifikat tata busana 4. Untuk formasi pengadministrasi umum (operator telepon) diutamakan berpendidikan SMK Perhotelan/ punya sertifikat pengalaman bekerja di hotel C. Syarat Kualifikasi Pendidikan No. Jabatan Formasi Kualifikasi Pendidikan 1 Supervisi Minimal SLTA berpengalaman dibidangnya dan diutamkan D3 ke atas 2 Binatu Rumah Sakit Minimal SLTA 3 Pemulasaran Jenazah Minimal SLTA 4 Pengadministrasi Umum (Pengelola Data) Minimal SLTA 5 Pengadministrasi Umum Minimal SLTA 6 Pengadministrasi Umum (operator telepon) Minimal SLTA 7 Pengadministrasi Umum (Penata Rekening) Minimal SLTA 8. Pengelola Limbah Minimal SLTA 9. Pengemudi Ambulan Minimal SLTA 10. Pengemudi Pimpinan Minimal SLTA 11. Teknisi Prasarana Minimal SLTA', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 340278);
