INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62271169', 62271169, 'analyze_legacy', 'Kota Mojokerto', 'kabkota', 'DINAS PERPUSTAKAAN DAN KEARSIPAN', 'Belanja Jasa Lainnya Perorangan pada Dinas Perpustakaan dan Kearsipan', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Mojokerto (Kota)', 237600000, 'January 2026', 'APBD', 1, 1, '9 Orang', '1) Tenaga Administrasi Perkantoran: 2 Orang; 2) Tenaga Frontliner: 2 Orang; 3) Tenaga Keamanan untuk Gudang/Depo Arsip dan/atau Kantor Dinas Perpustakaan dan Kearsipan Kota Mojokerto: 5 Orang;', 'A. TENAGA ADMINISTRASI PERKANTORAN 1. Pendidikan Minimal S1 2. Bertugas membantu tugas-tugas administrasi pada bidang penugasannya meliputi menyiapkan peralatan dan akomodasi kantor, melakukan input data sebagai operator, melaksanakan kegiatan surat menyurat, mengelola dan mengarsipkan dokumen kantor, serta melaksanakan tugas kedinasan lainnya yang diperintahkan pimpinan Dinas Perpustakaan dan Kearsipan Kota Mojokerto baik tertulis maupun lisan. B. TENAGA FRONTLINER 1. Pendidikan minimal S1 2. Bertugas melaksanakan pelayanan perpustakaan pada Perpustakaan Umum Kota Mojokerto, Perpustakaan RTH dan Taman Pintar, dan Layanan Perpustakaan Keliling, serta melaksanakan tugas kedinasan lainnya yang diperintahkan pimpinan Dinas Perpustakaan dan Kearsipan Kota Mojokerto baik tertulis maupun lisan. C. TENAGA KEAMANAN GUDANG DEPO ARSIP 1. Pendidikan Minimal SMA/Sederajat 2. Bertugas membuka dan menutup pintu Gudang/Depo Arsip, melakukan penjagaan terhadap keamanan Gudang/Depo Arsip dan Ruang Simpan Arsip sesuai dengan jadwal yang telah ditentukan, mencatat setiap tamu yang datang ke Gudang/Depo Arsip, melaporkan kepada pimpinan setiap kejadian di area di lingkungan Gudang/Depo Arsip, serta melaksanakan tugas kedinasan lainnya yang diperintahkan pimpinan Dinas Perpustakaan dan Kearsipan Kota Mojokerto baik tertulis maupun lisan. D. TENAGA KEAMANAN KANTOR DINAS PERPUSTAKAAN DAN KEARSIPAN 1. Pendidikan minimal SMA/Sederajat 2. Membantu penyeberangan masuk dan keluar kendaraan pegawai, tamu dan pengunjung; bertanggung jawab penuh atas masuk dan/atau keluarnya tamu dan pengunjung; menjaga keamanan dan ketertiban lingkungan dinas; melayani tamu dan pengunjung, termasuk menanyakan kepentingan kedatangan serta mengarahkan sesuai tujuan kedatangan pengunjung, dan memberikan instruksi tata tertib di lingkungan dinas; membantu membersihkan halaman dinas dan lingkungan kerja; serta melaksanakan tugas kedinasan lainnya yang diperintahkan pimpinan Dinas Perpustakaan dan Kearsipan Kota Mojokerto baik tertulis maupun lisan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 343598);
