INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62271099', 62271099, 'analyze_legacy', 'Pusat Pelaporan Dan Analisis Transaksi Keuangan', 'central', 'PUSAT PELAPORAN DAN ANALISIS TRANSAKSI KEUANGAN', 'Pengadaan Layanan Internet Pertama (1st Link) pada Pusat Pelaporan Dan Analisis Transaksi Keuangan Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 439650000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 0, 1, '12 Bulan', 'Layanan Internet Pertama (1st Link) pada Gedung Pusat Pelaporan Dan Analisis Transaksi Keuangan selama 12 Bulan pada Tahun 2026', 'Layanan Internet Pertama (1st Link): 1) Jenis Layanan: a) IP Transit dedicated b) Bandwidth sebesar 400 Mbps dengan rasio CIR (Commited Information Rate) 1:1 c) Jalur gabungan domestik dan internasional d) Mendukung pengumuman prefix milik instansi e) Menyediakan 2 IP Address Publik untuk koneksi CE (customer edge) dan PE (provider edge) antara PPATK dengan ISP Bandwidth CIR (Commited Information Rate) 1:1 2) Protokol Routing a) BGP b) Default route only (no full route) c) Mendukung blackhole dan traffic-engineering 3) Interface dan tipe konektor yang terhubung ke perangkat CE (customer edge) PPATK adalah 1G RJ‐45 4) Perangkat aktif milik ISP yang dipasang di PPATK dan digunakan untuk layanan ini harus memiliki redundant power supply 5) Service Level Agreement (SLA) a) Uptime ≥ 99,9% per bulan (dari jumlah bandwidth yang disewa) b) Response time (corrective maintenance) max 1 jam setelah laporan 6) Sanggup menyediakan kenaikan bandwidth temporer (bandwidth-on-demand) minimal 200% dari bandwidth yang sedang disewa (sebanyak 18 hari untuk periode 1 tahun) sesuai dengan prosedur yang berlaku di ISP dan menyediakan teknisi onsite ketika bandwidth-on demand berlangsung. 7) Sanggup menyediakan layanan DNS advertise untuk domain dan sub‐domain PPATK. 8) Dukungan Teknis a) NOC 24x7 dengan kontak eskalasi b) Kunjungan technical support saat dibutuhkan sepanjang 24x7 c) Layanan pengawasan gangguan secara dini (preventive support) 9) Pemantauan: portal pemantauan online 24x7 untuk pengguna 10) Laporan Rutin Wajib disampaikan secara bulanan melalui email, minimal berisi informasi sebagai berikut: a) Statistik dan/atau grafik penggunaan bandwidth b) Laporan jumlah dan persentase uptime dan downtime c) Log insiden dan penanganan d) History gangguan (planned/unplanned) 1) Ketentuan Pengenaan Denda Downtime: Apabila layanan internet yang disediakan mengalami downtime, Penyedia dikenakan denda dengan ketentuan perhitungan sebagai berikut: Denda=(A-Av)/C x B Dengan keterangan sebagai berikut: A: Jumlah jam gangguan dalam bulan gangguan Av: (100% - % tingkat availability) x jumlah jam Bulan gangguan B: Biaya langganan bulanan C: Jumlah jam dalam bulan gangguan % Tingkat Availability sesuai SLA sebesar 99,9% Denda dihitung sejak gangguan terjadi berdasarkan catatan/log sistem PPATK sampai gangguan tersebut dapat diatasi dan akan dipotong langsung pada saat pembayaran tagihan bulan berkenaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 344326);
