INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62975574', 62975574, 'analyze_legacy', 'Provinsi Jawa Barat', 'provinsi', 'Biro Umum', 'Jasa Konsultansi Pengawasan Plaza Area Depan Gedung Sate - Gasibu', 'Jasa Konsultansi', 'Seleksi', 'Jawa Barat, Bandung (Kota)', 464300000, 'January 2026', 'APBD', 1, 1, '1', 'Tahapan Pelaksanaan, meliputi : i. Melakukan pengawasan mobilisasi personel, peralatan, material dan pemenuhan persyaratan perizinan pelaksnaan pekerjaan tersebut; ii. Melakukan reviu terhadap gambar kerja dan spesifikasinya; iii. Memberikan rekomendasi kepada PPK terhadap perubahan-perubahan pelaksanaan pekerjaan; iv. Melakukan pengawasan penggunaan tenaga kerja, material dan peralatan serta penerapan metode pelaksanaan pekerjaan konstruksi; v. melakukan pengawasan ketepatan waktu, biaya, pemenuhan persyaratan mutu dan volume serta penerapan keselamatan konstruksi; vi. mengumpulkan data dan informasi di lapangan untuk memberikan rekomendasi teknis tentang alternatif pemecahan masalah yang terjadi selama pekerjaan konstruksi; vii. membantu PPK dalam mempersiapkan penyelenggaraan rapat lapangan secara berkala dan merekomendasikan rapat insidental; viii. membantu PPK dalam menyusunan berita acara persetujuan kemajuan pekerjaan; dan ix. membuat catatan harian, menyusun laporan mingguan dan bulanan pelaksanaan pekerjaan pengawasan A. Tahap serah Terima Pertama (provisional hand over), meliputi : i. Menyusun daftar cacat mutu dan mengawasi perbaikannya sebelum serah terima pertama (provisional hand over); ii. Memeriksa dan melakukan evaluasi terhadap kelengkapan dokumen gambar as bulit sesuai dengan pelaksanaan pekerjaan di lapangan sebelum serah terima pertaman (provisional hand over); iii. Melakukan pengawasan demobilisasi personel dan peralatan sesuai jadwal pengawasan dan jadwal mobilisasi; iv. Membantu Menyusun Berita Acara Pekerjaan 100% (seratus persen) sebelum serah terima pertama (provisional hand over); v. Membantu PPK dalam Menyusun Berita Acara Serah Terima Pertama (provisional hand over); vi. Menyusun laporan akhir kegiatan pekerjaan pengawasan. B. Tahap serah terima akhir (final hand over), yang dapat melewati tahun anggaran dan merupakan layanan purna jual jasa konsultan, meliputi: i. Melakukan pemeriksaan terhadap hasil pekerjaan pemeliharaan; ii. Memberikan rekomendasi kepada PPK terkait penerbitan Berita Acara Serah Terima Akhir Pekerjaan (Final Hand Over)', 'Dokumen teknis sebagaimana dimaksud meliputi gambar detail, Rencana Kerja dan Syarat (RKS), dan rincian volume pelaksanaan pekerjaan. Uraian Tugas Tenaga Ahli : 1. Tenaga Ahli Arsitektur Lanskap • Menyusun organisasi kerja tim secara keseluruhan; • Mengkoordinasikan pelaksanaan pekerjaan terhadap semua hal yang berhubungan dengan kelancaran pekerjaan; • Melakukan reviu dokumen pengawasan bidang bangunan gedung sebagai dasar pembangunan; • Mengkoordinasikan hubungan kerja antar organisasi kerja sesuai tugas masing-masing dengan semua unsur proyek; • Membuat laporan mengenai data-data yang didapat serta menganalisa untuk mendapatkan output, guna penyusunan buku laporan pada setiap tahap kegiatan; • Melakukan penyesuaian gambar dan spesifikasi teknis bidang bangunan gedung dalam pelaksanaan bila ada perubahan; • Memberikan penjelasan terhadap persoalan-persoalan yang timbul selama masa pelaksanaan konstruksi; • Memberikan saran-saran pertimbangan dan rekomendasi tentang penggunaan bahan/material interior. 2. Tenaga Ahli Sipil. • Berkoordinasi dengan semua pihak dalam pelaksanaan pekerjaan; • Melakukan reviu dokumen pengawasan bidang Interior untuk dijadikan dasar pembangunan; • Melakukan penyesuaian gambar dan spesifikasi teknis bidang Interior dalam pelaksanaan bila ada perubahan; • Memberikan penjelasan terhadap persoalan-persoalan yang timbul selama masa pelaksanaan konstruksi; • Memberikan saran-saran pertimbangan dan rekomendasi tentang penggunaan bahan/material interior; • Membuat laporan mengenai data-data yang didapat serta menganalisa untuk mendapatkan output, guna penyusunan buku laporan pada setiap tahap kegiatan. 3. Tenaga Ahli Elektrikal. • Berkoordinasi dengan semua pihak dalam pelaksanaan pekerjaan; • Melakukan reviu dokumen pengawasan bidang elektrikal untuk dijadikan dasar pembangunan; • Melakukan penyesuaian gambar dan spesifikasi teknis bidang elektrikal dalam pelaksanaan bila ada perubahan; • Memberikan penjelasan terhadap persoalan-persoalan yang timbul selama masa pelaksanaan konstruksi; • Memberikan saran-saran pertimbangan dan rekomendasi tentang penggunaan bahan/material elektrikal; • Membuat laporan mengenai data-data yang didapat serta menganalisa untuk mendapatkan output, guna penyusunan buku laporan pada setiap tahap kegiatan. 4. Tenaga Ahli K-3 • Menyusun organisasi kerja tim secara keseluruhan; • Mengkoordinasikan pelaksanaan pekerjaan terhadap semua hal yang berhubungan dengan kelancaran pekerjaan; • Mengkoordinasikan hubungan kerja antar organisasi kerja sesuai tugas masing-masing dengan semua unsur proyek; • Melakukan reviu dokumen pengawasan bidang K-3 untuk dijadikan dasar pembangunan; • Membuat laporan mengenai data-data yang didapat serta menganalisa untuk mendapatkan output, guna penyusunan buku laporan pada proses pengawasan berkala; • Memberikan penjelasan terhadap persoalan-persoalan yang timbul selama masa pelaksanaan konstruksi; • Memberikan saran-saran pertimbangan dan rekomendasi tentang pelaksanaan K-3 5. Ahli Arkeologi. • Berkoordinasi dengan semua pihak dalam pelaksanaan pekerjaan; • Melakukan reviu dokumen pengawasan bidang arkeolog untuk dijadikan dasar pembangunan; • Melakukan penyesuaian gambar dan spesifikasi teknis bidang arkeolog dalam pelaksanaan bila ada perubahan; • Memberikan penjelasan terhadap persoalan-persoalan yang timbul selama masa pelaksanaan konstruksi; • Memberikan saran-saran pertimbangan dan rekomendasi tentang penggunaan bahan/material mekanikal; • Membuat laporan mengenai data-data yang didapat serta menganalisa untuk mendapatkan output, guna penyusunan buku laporan pada setiap tahap kegiatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 345293);
