INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62235832', 62235832, 'analyze_legacy', 'Lembaga Penyiaran Radio Republik Indonesia', 'central', 'RRI YOGYAKARTA', 'Pemeliharaan OB Van', 'Jasa Lainnya', 'Dikecualikan', 'DI Yogyakarta, Yogyakarta (Kota)', 32000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 2, Unit, @ 16000000 )', '1. Pemeliharaan OB Van ( 2, Unit, @ 16000000 );', 'Pengadaan jasa pemeliharaan OB Van dimaksudkan untuk menjaga kelaikan kendaraan dinas operasional siaran luar sekaligus memastikan peralatan teknologi siaran di dalamnya berfungsi optimal. OB Van digunakan sebagai sarana pendukung utama kegiatan siaran luar, sehingga diperlukan pemeliharaan terpadu agar selalu siap operasional. Ruang lingkup pekerjaan meliputi pemeliharaan kendaraan OB Van berupa servis ringan kendaraan, pengecekan mesin, sistem kelistrikan, rem, ban, dan sistem pendingin, serta pemeliharaan peralatan teknologi siaran yang terpasang di dalam kendaraan, seperti sistem audio, video, perangkat kontrol, kelistrikan internal, dan konektivitas pendukung. Pemeliharaan dilakukan oleh tenaga teknis yang kompeten sesuai bidangnya, dengan memastikan seluruh sistem kendaraan dan peralatan siaran berfungsi baik, aman, dan siap digunakan sesuai standar operasional siaran luar.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 346275);
