INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62235820', 62235820, 'analyze_legacy', 'Lembaga Penyiaran Radio Republik Indonesia', 'central', 'RRI YOGYAKARTA', 'Langganan Internet', 'Jasa Lainnya', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 84000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 12, Bln, @ 7000000 )', '1. Langganan Internet ( 12, Bln, @ 7000000 );', 'Belanja langganan internet dimaksudkan untuk mendukung kelancaran kegiatan operasional perkantoran, komunikasi data, serta pelaksanaan tugas kedinasan yang membutuhkan akses internet cepat dan stabil. Layanan internet digunakan untuk menunjang aktivitas administrasi, produksi konten, dan koordinasi secara daring. Ruang lingkup belanja meliputi layanan akses internet dengan kecepatan minimal 150 Mbps, koneksi stabil, layanan teknis (support) selama masa berlangganan, serta penyediaan jaringan oleh penyelenggara jasa internet resmi (ISP berizin). Layanan harus tersedia secara berkelanjutan sesuai periode langganan dan memenuhi standar kualitas layanan yang disepakati.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 347097);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62976456', 62976456, 'analyze_legacy', 'Badan Narkotika Nasional', 'central', 'BALAI BESAR REHABILITASI BADAN NARKOTIKA NASIONAL', 'Belanja Bahan', 'Barang', 'Pengadaan Langsung', 'Jawa Barat, Bogor (Kab.)', 50400000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Bahan penunjang ( 168, PKT, @ 300000 );', '1. Bahan penunjang ( 168, PKT, @ 300000 );', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 347098);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62235819', 62235819, 'analyze_legacy', 'Lembaga Penyiaran Radio Republik Indonesia', 'central', 'RRI YOGYAKARTA', 'Kendaraan Bermotor Roda 4 Eselon II', 'Jasa Lainnya', 'Dikecualikan', 'DI Yogyakarta, Yogyakarta (Kota)', 111000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 3, Unit, @ 37000000 )', '1. Kendaraan Bermotor Roda 4 Eselon II ( 3, Unit, @ 37000000 );', 'Pemeliharaan ringan kendaraan bermotor roda-4 Eselon II dimaksudkan untuk menjaga kondisi, kenyamanan, dan kelaikan operasional kendaraan dinas pimpinan agar selalu siap digunakan dalam mendukung pelaksanaan tugas kedinasan. Pemeliharaan dilakukan secara berkala tanpa pembongkaran besar, dengan memperhatikan standar perawatan kendaraan dinas pimpinan. Ruang lingkup pekerjaan meliputi servis ringan kendaraan, antara lain penggantian oli mesin, pengecekan dan pembersihan filter udara, pemeriksaan sistem rem dan sistem pendingin mesin, pengecekan aki, kondisi ban, sistem kelistrikan, serta kelengkapan kendaraan lainnya. Selain itu, belanja ini mencakup pembelian Bahan Bakar Minyak (BBM) sesuai jenis kendaraan untuk mendukung mobilitas dan kegiatan operasional kendaraan dinas Eselon II, dengan penggunaan yang tertib, efisien, dan dapat dipertanggungjawabkan sesuai ketentuan peraturan perundang-undangan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 347099);
